CustomField.formula:
IF( NOT(ISBLANK(Unit__r.Unit_Sold_Date__c)),
IF( OR( Unit__r.Category__c = "MEGA MANSIONS", Unit__r.Category__c = "MANSIONS" ), /* Special rule for Mansions categories */ CASE(ProjectName__c, "Nawayef West", IF(Unit__r.Unit_Sold_Date__c <= DATE(2024, 11, 30), TotalAmount__c * 0.02, TotalAmount__c * 0.03), "Nawayef East", IF(Unit__r.Unit_Sold_Date__c <= DATE(2024, 11, 30), TotalAmount__c * 0.02, TotalAmount__c * 0.03), 0 ), /* Standard rule for other categories */ CASE(ProjectName__c, "Al Naseem", IF(Unit__r.Unit_Sold_Date__c <= DATE(2024, 11, 30), TotalAmount__c * 0.02, TotalAmount__c * 0.04), "Muheira", TotalAmount__c * 0.04, "Maysan", TotalAmount__c * 0.03, "Nawayef West", IF(Unit__r.Unit_Sold_Date__c <= DATE(2024, 11, 30), TotalAmount__c * 0.02, TotalAmount__c * 0.04), "Nawayef East", IF(Unit__r.Unit_Sold_Date__c <= DATE(2024, 11, 30), TotalAmount__c * 0.02, TotalAmount__c * 0.04), "Nawayef Park View", TotalAmount__c * 0.03, "Nawayef Village Townhouses", TotalAmount__c * 0.04, 0 ) ),
/* If Unit_Sold_Date__c is blank, return blank */ NULL )
